-- ============================================================================
-- 0105: seed the Super Admin website content module with DRAFTS.
--
-- FOR REVIEW ONLY. NOT APPLIED TO ANY REMOTE PROJECT BY THIS CHANGE.
--
-- Generated by scripts/generate-site-content-seed.mjs from
-- app/about/page.tsx, app/contact/page.tsx, app/legal/*/page.tsx and
-- lib/legal/{documents,content}.ts. Re-run the script rather than editing this
-- file by hand.
--
-- What it does:
--   * inserts one row per public page (About, Contact and every policy in the
--     legal registry) ONLY when that slug does not exist yet, so it is
--     idempotent and never overwrites an edit made in /admin/content;
--   * copies the current wording into ordered sections;
--   * leaves every page in DRAFT. This migration publishes NOTHING.
--   * writes no published_at, no published_by and no published_snapshot, so no
--     page can be served to a customer by this file, and there is no backdated
--     publication timestamp anywhere;
--   * moves the operator notices ("Publication review required", the open
--     owner decisions) into site_page_admin_notes, which no customer can read.
--
-- It inserts NO approval: every page is marked owner_review_pending.
--
-- WHY DRAFTS AND NOT PUBLISHED
-- Publishing is an owner decision with a legal consequence: it is what makes a
-- policy publicly readable, and (for a document that is acceptance-required) what
-- fixes the version a customer must accept. A seed cannot make that decision for
-- 19 pages at once, and a fabricated historical timestamp would claim the owner
-- published them on a date they did not choose. Publication is therefore a
-- separate, reviewed, per-stage action:
--
--   supabase/publication/stage1_publish_live_text.sql
--   supabase/publication/stage2_publish_reviewed_additions.sql
--   (see supabase/publication/README.md for the order, the approvals and the
--    verification queries)
--
-- Depends on: 0104 (site_pages).
-- Rollback: supabase/rollbacks/0105_seed_site_content.down.sql
-- ============================================================================

do $$
begin
  if to_regclass('public.site_pages') is null then
    raise exception '0105 requires migration 0104 (site_pages).';
  end if;
end
$$;
-- terms
do $$
declare
  v_page uuid;
begin
  select id into v_page from public.site_pages where slug = $seed$terms$seed$;
  if v_page is not null then
    return;
  end if;

  insert into public.site_pages (
    slug, kind, audience, nav_label, short_label, eyebrow, title, intro,
    meta_description, status, version, effective_date, sort_order,
    show_in_footer, show_in_index, show_contact_details, related_slugs,
    is_system
  ) values (
    $seed$terms$seed$, $seed$legal$seed$, $seed$everyone$seed$, $seed$Terms$seed$, $seed$Terms$seed$,
    $seed$Legal policies$seed$, $seed$Terms and Conditions$seed$, $seed$These terms cover Maharani Traders’ current own-stock wholesale and retail sales.$seed$, $seed$The basic rules for using the website, placing orders and paying.$seed$,
    'draft', $seed$1.0$seed$, date '2026-11-04', 10,
    true, true, true, '{}'::text[],
    true
  ) returning id into v_page;

    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Acceptance and business model$seed$, array[$seed$By using the website, creating an account, placing an order or purchasing products, you agree to these terms and the applicable website policies. If you do not agree, please do not use the website.$seed$, $seed$Maharani Traders is a customer-facing brand operated by AJAY KUMAR, Proprietor, under the registered trade name AJAY GENERAL; it is not a separate incorporated company or legal entity. These policies cover own-stock cosmetics, personal-care products and non-food FMCG. Food products are excluded.$seed$, $seed$The application includes marketplace and seller features, including seller offers and fulfilment; their availability depends on configuration. These own-stock sales terms do not provide a complete set of terms for third-party seller transactions. Any third-party launch or ongoing operation requires separately reviewed customer and seller terms, including the seller of record, invoicing, fulfilment, returns and support responsibilities. Applicable rights are not excluded.$seed$]::text[], '{}'::text[], 10);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Product information, prices and taxes$seed$, array[$seed$We endeavour to display accurate product names, descriptions, photographs, prices and quantities. Packaging, colour and other visual details may vary. Please check the actual label, ingredients, directions, warnings, manufacturer details and expiry or use-before information before use.$seed$, $seed$Prices, applicable taxes, any delivery or compulsory charges, and applicable wholesale quantities, slabs or minimum orders will be displayed or communicated before confirmation. GST will be charged and invoiced as required by law. An obvious listing or pricing error may be corrected before order acceptance; if an amount was collected for an unfulfilled order, it will be refunded.$seed$]::text[], '{}'::text[], 20);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Order placement and acceptance$seed$, array[$seed$An order is a request to purchase, subject to stock availability, delivery serviceability and confirmation. We may contact you to verify the order, quantity, address or phone number.$seed$, $seed$An order may be declined or cancelled if the product is unavailable, the address is outside the serviceable area, information is incomplete or appears fraudulent, the listing contains a material error, or fulfilment would violate applicable law. Amounts collected for an unfulfilled cancelled order will be refunded.$seed$]::text[], '{}'::text[], 30);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Payment and customer responsibilities$seed$, array[$seed$The current cash payment method is Cash on Delivery (COD). The checkout may apply an available Coins balance automatically; the remaining confirmed amount is payable to an authorised delivery representative on delivery. Review the checkout total before confirming.$seed$, $seed$Provide accurate contact and delivery information, check your order, keep account credentials confidential, use the site lawfully and pay the confirmed COD balance when accepting delivery. Do not send money to an unknown personal account or unauthorised payment link. Additional payment methods, if introduced, will be displayed before use.$seed$]::text[], '{}'::text[], 40);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Intellectual property and applicable law$seed$, array[$seed$The Maharani Traders name, original site design, logos, text and graphics may not be reproduced or commercially used without permission except as permitted by law. Third-party product names and trademarks belong to their respective owners.$seed$, $seed$Nothing in these terms excludes a right or remedy that cannot lawfully be excluded. Indian law applies; disputes may be handled by the competent authority or court having jurisdiction under applicable law. See our [cancellation and return policy](/legal/returns) and [contact details](/contact).$seed$]::text[], '{}'::text[], 50);

  -- Deliberately NOT published here: see the header. The page stays a draft
  -- until the owner runs a publication stage for its slug.

  insert into public.site_page_admin_notes (page_id, internal_notes, owner_decisions, review_status)
  values (v_page, $seed$Owner verification pending. This wording was published before website content management existed and was carried over verbatim by migration 0105 so no customer-visible policy text changed. It still requires the owner and an Indian legal/tax reviewer to confirm the commercial points listed in the open decisions.$seed$, '{}'::text[], 'owner_review_pending')
  on conflict (page_id) do nothing;
end
$$;

