    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Information we may collect$seed$, array[$seed$Depending on your use, we may collect your name, mobile number, email, billing and delivery addresses, order and purchase history, COD collection and payment status, support messages and complaints, account, login and device-related information, and information needed for tax, accounting, security, fraud prevention or legal compliance.$seed$, $seed$Do not send passwords, OTPs or unnecessary sensitive personal information through customer support.$seed$]::text[], '{}'::text[], 10);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$How information is used and shared$seed$, array[$seed$Information may be used to manage accounts, confirm and deliver orders, communicate about orders and returns, maintain invoices and tax records, handle support and refunds, detect fraud and misuse, improve the website and comply with applicable law. Unrelated uses require an appropriate lawful basis.$seed$, $seed$Where necessary and lawful, information may be shared with delivery providers, technology and security providers, professional advisers or authorities. The application also supports third-party seller fulfilment: if used, the relevant seller may receive order and delivery information, including the recipient address and phone where provided. Marketplace data flows and disclosures require verification before any third-party operation. We do not sell customer personal information as a business practice. The application uses Supabase for authentication and includes Vercel Analytics; actual deployment and provider arrangements should be verified before publication.$seed$]::text[], '{}'::text[], 20);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Cookies and security$seed$, array[$seed$The site may use cookies or similar technologies for login, cart functionality, security, preferences and performance. Any legally required consent mechanism must be implemented and verified before publication. Browser settings can control cookies, but disabling essential cookies may affect functionality.$seed$, $seed$Reasonable technical and organisational measures are intended to protect information, but no internet service can guarantee absolute security. Use strong passwords and do not share OTPs or login credentials.$seed$]::text[], '{}'::text[], 30);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Retention, requests and updates$seed$, array[$seed$Information may be retained for fulfilment, accounting, tax, complaint handling, disputes and legal compliance. Retention periods and deletion procedures require verification; some transaction or tax records may need statutory retention.$seed$, $seed$For questions, corrections or other privacy requests, contact AJAY KUMAR, Proprietor, using the details below. Requests will be reviewed under applicable law. This policy may be updated when practices or requirements change; the latest version will carry its effective date.$seed$, $seed$Proprietor: AJAY KUMAR$seed$, $seed$Registered trade name: AJAY GENERAL$seed$, $seed$Brand: MAHARANI TRADERS$seed$, $seed$Grievance Officer: AJAY KUMAR, Proprietor$seed$, $seed$Address: Plot No. 231, Ander Bazar, Belaganj, Gaya, Bihar – 804403$seed$, $seed$Phone: [8987023959](tel:8987023959)$seed$, $seed$Email: [adinathsahu8987@gmail.com](mailto:adinathsahu8987@gmail.com)$seed$]::text[], '{}'::text[], 40);

  -- Deliberately NOT published here: see the header. The page stays a draft
  -- until the owner runs a publication stage for its slug.

