    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Order cancellation$seed$, array[$seed$Contact us as soon as possible to request cancellation. A request before dispatch may be accepted; an order already dispatched may not be cancellable through the ordinary process. Cancellation depends on order status and applicable law. If we cancel an order after collecting payment, the amount paid for the unfulfilled order will be refunded.$seed$]::text[], '{}'::text[], 10);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Product issues and return requests$seed$, array[$seed$Contact us if a product is damaged, defective, wrong, a wrong quantity, materially different from its description, suspected spurious or non-genuine, or has a relevant labelling, quality or legal issue. We will review the complaint and provide the remedy required by applicable law, which may include replacement, return, refund or another appropriate remedy.$seed$, $seed$Please provide your order number, name and mobile number, product and quantity, issue description and photographs or video if reasonably available. We may ask for additional information; a missing photograph alone does not automatically remove statutory rights.$seed$, $seed$The website return-request form may have an order-specific deadline. If the form is closed, contact support; an internal deadline does not remove statutory rights or remedies.$seed$]::text[], '{}'::text[], 20);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Cosmetics, hygiene and refunds$seed$, array[$seed$A change-of-mind return for opened or used cosmetics may be refused for hygiene and safety where lawful. This does not prevent a legally available remedy for a defective, damaged, wrong, spurious or misdescribed product.$seed$, $seed$For an approved COD refund, support will arrange a reasonable and lawful refund method and verify necessary details. We will communicate an expected processing time after approval. Never share an OTP, password or card PIN to obtain a refund. No unverified blanket return period or automatic refund is promised.$seed$, $seed$Nothing in this policy limits rights or remedies available under applicable consumer-protection or other Indian law.$seed$]::text[], '{}'::text[], 30);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Return and refund contact$seed$, array[$seed$Proprietor: AJAY KUMAR$seed$, $seed$Registered trade name: AJAY GENERAL$seed$, $seed$Brand: MAHARANI TRADERS$seed$, $seed$Grievance Officer: AJAY KUMAR, Proprietor$seed$, $seed$Address: Plot No. 231, Ander Bazar, Belaganj, Gaya, Bihar – 804403$seed$, $seed$Phone: [8987023959](tel:8987023959)$seed$, $seed$Email: [adinathsahu8987@gmail.com](mailto:adinathsahu8987@gmail.com)$seed$]::text[], '{}'::text[], 40);

