    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Serviceability, charges and estimates$seed$, array[$seed$Delivery is available only when the address is confirmed as serviceable by the website or support. Not all Gaya PINs are serviceable; we do not promise delivery throughout Gaya district or Bihar. An active serviceable PIN and applicable minimum order are checked at checkout.$seed$, $seed$Delivery or other compulsory charges will be disclosed before confirmation. If no charge is shown, confirm it with support before placing an order. The current checkout blocks online ordering for PINs configured with a positive delivery fee until that fee can be accounted for correctly.$seed$, $seed$Estimated timing will be communicated at checkout or confirmation, depending on availability and location. Estimates can be affected by weather, local conditions or operational issues. Contact support about significant delays; order status is not real-time location tracking.$seed$]::text[], '{}'::text[], 10);
