    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Check the goods at delivery$seed$, array[$seed$Delivery is completed with a one-time password (OTP) that only you receive. Please count and inspect the goods before you share the OTP with the delivery person.$seed$, $seed$If any item is missing or visibly damaged, tell the delivery person before the delivery is completed. They record the missing or damaged quantity against each item, and the delivery is saved as a partial delivery.$seed$]::text[], '{}'::text[], 10);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$What happens for a shortfall recorded at the door$seed$, array[$seed$You pay only for the goods actually delivered. The amount to collect is recalculated from the quantities recorded.$seed$, $seed$If Coins were applied to goods that were not delivered, the value of that shortfall is credited back to your Coins balance. The system calculates this amount from the recorded quantities; it cannot be typed in by the delivery person.$seed$]::text[], '{}'::text[], 20);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Problems found after delivery$seed$, array[$seed$Raise a return request from the order page, or contact us using the details below. Each delivered order shows the last date for raising a return request in the app. If that date has passed, you can still contact us: an internal deadline does not take away a remedy the law gives you.$seed$, $seed$Tell us the order number, the product, the quantity affected and what is wrong. Photographs of the product, the batch number and the outer carton help us act quickly and trace the batch. A missing photograph does not by itself defeat a valid complaint.$seed$]::text[], array[$seed$Damaged in transit or leaking.$seed$, $seed$Wrong product, wrong variant or wrong quantity.$seed$, $seed$Expired, or past its “use before” date when delivered.$seed$, $seed$Seal broken, label missing or label does not match the listing.$seed$, $seed$Suspected counterfeit or not genuine.$seed$]::text[], 30);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$How we resolve it$seed$, array[$seed$After checking the complaint we will offer the remedy that fits the problem: replacement, collection of the goods with a refund, or a price adjustment. For goods sold by an independent seller, we pass the complaint to that seller and follow it up; see the Marketplace Disclaimer.$seed$, $seed$Please keep the product, its packaging and the invoice until the complaint is closed. Do not use or resell a product you believe is unsafe or not genuine.$seed$, $seed$Opened or used cosmetics and personal-care products are not accepted back for a change of mind, for hygiene reasons. This does not apply where the product is defective, damaged, wrong, expired or not genuine.$seed$]::text[], '{}'::text[], 40);

