    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Who can sell$seed$, array[$seed$Selling is by invitation only. A seller account is created only from an invitation issued by the Super Admin. There is no public seller sign-up.$seed$, $seed$Before the account is activated the seller must provide true and current business details and documents for verification, including legal name, business address, GST registration details and PAN where applicable, and bank account details for payouts. The seller must tell us promptly if any of these change.$seed$, $seed$We may refuse, pause or end onboarding if details cannot be verified.$seed$]::text[], '{}'::text[], 10);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$What can be listed$seed$, array[$seed$Only cosmetics, personal-care and non-food FMCG goods in categories that we have approved may be listed. Food and drink of every kind are not permitted on this website. See the Prohibited and Restricted Products Policy.$seed$, $seed$Every offer is reviewed before it is shown to buyers. We keep a record of each approval, rejection and suspension and the reason for it.$seed$]::text[], '{}'::text[], 20);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Seller’s promises about the goods$seed$, '{}'::text[], array[$seed$The goods are genuine, lawfully sourced and the seller has the right to sell them.$seed$, $seed$Cosmetics are made by a licensed manufacturer or lawfully imported, and carry the label particulars required by the Cosmetics Rules, 2020.$seed$, $seed$Pre-packaged goods carry the declarations required by the Legal Metrology (Packaged Commodities) Rules, 2011, including MRP, net quantity, month and year of manufacture or packing, manufacturer or importer details, consumer-care details and, for imported goods, country of origin.$seed$, $seed$Goods are not expired, recalled, tampered with or re-labelled, and have a reasonable remaining shelf life when dispatched.$seed$, $seed$The description, images, price and stock shown on the listing are accurate and are kept up to date.$seed$, $seed$The seller will give us invoices, licences, test reports or brand authorisations when we ask for them to check a listing or a complaint.$seed$]::text[], 30);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Orders, delivery and returns$seed$, array[$seed$The seller must make the ordered goods ready in the quantity and condition ordered. If the seller cannot fulfil an order it must tell us at once so the buyer can be informed.$seed$, $seed$The seller is responsible for the goods it sells and must accept back, replace or refund goods that are damaged, defective, wrong, expired, not genuine or not as described, in line with the policies published on this website and with the law.$seed$, $seed$The seller must name a person who will respond to buyer complaints that we forward, and must respond within the timelines in the Grievance Redressal Policy.$seed$]::text[], '{}'::text[], 40);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Prices, taxes, fees and payouts$seed$, array[$seed$The seller sets its selling price, which must not exceed the MRP printed on the pack. The seller is the supplier of its goods for GST purposes and is responsible for its own tax invoices, returns and tax payments.$seed$, $seed$Our commission or fees, and the payout cycle, are those agreed with the seller in writing and recorded against the seller account. Payouts are made after deducting agreed fees, refunds, and any tax that the law requires us to collect or deduct on the seller’s sales, and are shown in the seller ledger.$seed$, $seed$We may hold a payout for an order that is the subject of an open complaint, return or investigation until it is resolved.$seed$]::text[], '{}'::text[], 50);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Buyer data$seed$, array[$seed$The seller receives only the buyer information needed to fulfil an order. It must be used only for that order, kept secure, and not used for marketing or shared with anyone else.$seed$]::text[], '{}'::text[], 60);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Suspension and ending the agreement$seed$, array[$seed$We may remove a listing or suspend a seller where there is a safety concern, a suspected counterfeit, a breach of this agreement or of the law, or a failure to respond to complaints. When a seller is suspended its offers are withdrawn from sale automatically.$seed$, $seed$Either side may end the agreement by written notice. Orders already accepted, complaints, returns, payouts due and record-keeping duties continue until they are completed. See the Suspension, Termination and Dispute Policy.$seed$]::text[], '{}'::text[], 70);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Changes to this agreement$seed$, array[$seed$When this agreement changes we publish a new version with a new version number and date. A seller is asked to accept the new version; the version accepted and the time of acceptance are recorded.$seed$]::text[], '{}'::text[], 80);

  -- Deliberately NOT published here: see the header. The page stays a draft
  -- until the owner runs a publication stage for its slug.

  insert into public.site_page_admin_notes (page_id, internal_notes, owner_decisions, review_status)
  values (v_page, $seed$Owner verification pending. This wording was published before website content management existed and was carried over verbatim by migration 0105 so no customer-visible policy text changed. It still requires the owner and an Indian legal/tax reviewer to confirm the commercial points listed in the open decisions.$seed$, array[$seed$Commission / fee rates and the payout cycle (kept out of this document on purpose; they must be agreed in writing with each seller).$seed$, $seed$Whether the operator has registered for, and will collect, tax at source on seller sales under section 52 of the CGST Act, and deduct tax under section 194-O of the Income-tax Act. Confirm with a Chartered Accountant before the first third-party sale.$seed$, $seed$Liability caps, indemnity wording, notice period and governing court: to be settled by a lawyer before the first seller is onboarded.$seed$]::text[], 'owner_review_pending')
  on conflict (page_id) do nothing;
