-- retailer-terms
do $$
declare
  v_page uuid;
begin
  select id into v_page from public.site_pages where slug = $seed$retailer-terms$seed$;
  if v_page is not null then
    return;
  end if;

  insert into public.site_pages (
    slug, kind, audience, nav_label, short_label, eyebrow, title, intro,
    meta_description, status, version, effective_date, sort_order,
    show_in_footer, show_in_index, show_contact_details, related_slugs,
    is_system
  ) values (
    $seed$retailer-terms$seed$, $seed$legal$seed$, $seed$buyers$seed$, $seed$Retailer terms$seed$, $seed$Retailer terms$seed$,
    $seed$Legal policies$seed$, $seed$Retailer and Wholesale Buyer Terms$seed$, $seed$Additional terms for shops and wholesale buyers. They apply together with the general Terms and Conditions.$seed$, $seed$Extra terms for shops buying for resale: account approval, pricing category, resale duties.$seed$,
    'draft', $seed$1.0$seed$, date '2026-11-14', 70,
    true, true, true, array[$seed$terms$seed$, $seed$returns$seed$, $seed$damaged-goods$seed$, $seed$coins-loyalty$seed$, $seed$gst-pricing-invoice$seed$]::text[],
    true
  ) returning id into v_page;

    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Who can buy$seed$, array[$seed$This website serves retailers and wholesale buyers in the areas we deliver to. An account is reviewed before it can place orders. Please give true shop details, including the shop name, address, mobile number and, if you are registered, your GSTIN.$seed$, $seed$You are responsible for orders placed from your account. Keep your password private and tell us at once if you think someone else has used your account.$seed$]::text[], '{}'::text[], 10);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Prices and your pricing category$seed$, array[$seed$Prices, pack sizes, minimum quantities and any quantity slabs are shown before you confirm an order. The price that applies is the one shown at checkout for your account.$seed$, $seed$Your account may be placed in a pricing category by our team. A category is not a paid membership: there is no fee, no subscription and no renewal. We may change a category, and the change applies to orders placed after it.$seed$]::text[], '{}'::text[], 20);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Payment$seed$, array[$seed$Orders are paid by Cash on Delivery. Any Coins balance applied is shown at checkout, and the remaining amount is payable to our delivery person when you accept the goods. Pay only against the order shown in the app, and never share your delivery OTP before you have checked the goods.$seed$]::text[], '{}'::text[], 30);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Resale$seed$, '{}'::text[], array[$seed$Sell the goods in their original, unopened packs, with the label intact.$seed$, $seed$Do not sell above the MRP printed on the pack.$seed$, $seed$Do not sell goods after the “use before” or expiry date. Store goods as the label directs.$seed$, $seed$If we tell you about a recall or a safety problem with a batch, stop selling it and follow our instructions.$seed$]::text[], 40);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Your rights as a business buyer$seed$, array[$seed$Some consumer-protection laws apply only to people who buy for personal use and may not apply to goods bought for resale. Whatever the legal position, the complaint, return and grievance procedures published on this website are open to every buyer.$seed$]::text[], '{}'::text[], 50);

  -- Deliberately NOT published here: see the header. The page stays a draft
  -- until the owner runs a publication stage for its slug.

  insert into public.site_page_admin_notes (page_id, internal_notes, owner_decisions, review_status)
