    $seed$Legal policies$seed$, $seed$Marketplace Disclaimer$seed$, $seed$This website sells goods from our own stock and can also show offers from independent sellers. This page explains the difference.$seed$, $seed$Which goods are sold by us and which by independent sellers, and who is responsible for what.$seed$,
    'draft', $seed$1.0$seed$, date '2026-11-14', 80,
    true, true, true, array[$seed$seller-agreement$seed$, $seed$product-safety$seed$, $seed$grievance$seed$, $seed$ip-complaints$seed$]::text[],
    true
  ) returning id into v_page;

    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Two kinds of offer$seed$, array[$seed$Own stock: goods bought, stored and sold by Maharani Traders. We are the seller and issue the invoice.$seed$, $seed$Seller offer: goods offered by an independent seller that we have invited and verified. That seller is the seller of those goods and is responsible for their quality, labelling, authenticity and tax invoice. The offer shows the seller’s name.$seed$]::text[], '{}'::text[], 10);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$What we do for seller offers$seed$, '{}'::text[], array[$seed$Invite sellers individually and check their business details before they can list.$seed$, $seed$Review each offer before it is shown, and allow only approved cosmetics and non-food FMCG categories.$seed$, $seed$Take a written agreement from each seller that goods are genuine and correctly labelled.$seed$, $seed$Receive your complaints, forward them to the seller, and follow them up to a conclusion.$seed$, $seed$Remove listings and suspend sellers where we find a problem.$seed$]::text[], 20);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$What we do not do$seed$, array[$seed$We do not manufacture any product sold here. We do not make any health, medical or treatment claim for any product. Product descriptions and images for seller offers come from the seller; always read the label on the pack before using or reselling a product.$seed$, $seed$This page does not limit any liability that the law places on a marketplace operator or on a seller, and it does not limit your right to complain to us about any order placed on this website.$seed$]::text[], '{}'::text[], 30);

