    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$How to submit a complaint$seed$, array[$seed$Call 8987023959, email [adinathsahu8987@gmail.com](mailto:adinathsahu8987@gmail.com), or use the [website Help centre](/retailer/help) where available. Include your order number, contact details and a clear description.$seed$]::text[], '{}'::text[], 20);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
