    is_system
  ) values (
    $seed$gst-pricing-invoice$seed$, $seed$legal$seed$, $seed$everyone$seed$, $seed$GST & invoices$seed$, $seed$GST & invoices$seed$,
    $seed$Legal policies$seed$, $seed$GST, Pricing and Invoice Policy$seed$, $seed$How prices and taxes are shown on this website and what invoice you receive.$seed$, $seed$How prices and taxes are shown, and when a tax invoice is issued.$seed$,
    'draft', $seed$1.0$seed$, date '2026-11-14', 110,
    true, true, true, array[$seed$terms$seed$, $seed$retailer-terms$seed$, $seed$seller-agreement$seed$, $seed$business-disclosure$seed$]::text[],
    true
  ) returning id into v_page;

    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Prices$seed$, array[$seed$The price for each product, the pack size and the quantity are shown before you place an order, and the order summary shows the total payable. Any delivery or other charge is shown separately before you confirm.$seed$, $seed$No product is sold above the Maximum Retail Price (MRP) printed on its pack. If a pack you receive shows a lower MRP than the price charged, tell us and we will correct it.$seed$, $seed$If a price was shown wrongly because of an obvious error, we will contact you before dispatch and you may cancel the order without any charge.$seed$]::text[], '{}'::text[], 10);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$GST$seed$, array[$seed$Where GST applies, it is charged at the rate that applies to the product and is shown in the order summary and on the invoice.$seed$, $seed$If you want your GSTIN on the invoice, add the correct GSTIN and registered business name to your account before placing the order. We cannot add or change a GSTIN on an invoice that has already been issued, except as the GST law allows.$seed$]::text[], '{}'::text[], 20);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Invoices$seed$, array[$seed$An invoice or bill is issued for every delivered order by the seller of the goods: by us for own-stock goods, and by the independent seller for seller offers. Where one order contains goods from more than one seller, you may receive more than one invoice.$seed$, $seed$The app shows a tax invoice only when the registration and tax details needed for a valid tax invoice are complete. Until then the document is marked as an order summary and is not a tax invoice.$seed$, $seed$For returns and price corrections, a credit note or revised document is issued as the GST law requires.$seed$]::text[], '{}'::text[], 30);

  -- Deliberately NOT published here: see the header. The page stays a draft
