    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Product information and safety$seed$, array[$seed$We will take reasonable steps to offer products that are lawfully sourced, carry applicable manufacturer, packer or importer information and declarations such as batch, quantity, MRP, manufacturing and expiry or use-before details, and display applicable warnings and usage information.$seed$, $seed$We will not knowingly offer products after expiry or where sale is prohibited by law. Customers should check labels and instructions before use, stop using a product if they discover a safety, quality or labelling concern, and contact support.$seed$, $seed$Maharani Traders does not claim to manufacture branded products it resells unless expressly stated for a particular product. Current policy scope is cosmetics and non-food FMCG; food is excluded.$seed$]::text[], '{}'::text[], 10);
