    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$How this is enforced$seed$, array[$seed$Every product category carries a compliance classification set by the Super Admin. Only categories classified as cosmetics or non-food FMCG can hold products for sale; the database rejects a product or seller offer placed in any other category.$seed$, $seed$Seller offers are reviewed before they go live, and each decision is recorded with the reviewer and the reason.$seed$]::text[], '{}'::text[], 20);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
