    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$How we do it$seed$, array[$seed$Where it is safe to do so we tell you the reason and give you a chance to explain before a lasting restriction. Where there is a risk to buyers, to payments or to the security of the service, we may act first and tell you afterwards.$seed$, $seed$Restriction decisions are recorded with the reason and the person who made them.$seed$]::text[], '{}'::text[], 20);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Closing your own account$seed$, array[$seed$A retailer can ask for account closure from Account → Security in the app, or by contacting us. Open orders, returns and amounts due are settled first.$seed$, $seed$After closure we delete or anonymise personal data that we no longer need, and keep only what the law requires us to keep, such as invoices and tax and accounting records, for the period the law requires. See the Privacy Policy.$seed$]::text[], '{}'::text[], 30);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
