    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$What is stored and why$seed$, '{}'::text[], array[$seed$Sign-in session cookies: keep you signed in securely and protect your account. They are necessary; the website cannot work without them.$seed$, $seed$Device storage for convenience: recently viewed products, recent searches, your product-comparison list and whether you dismissed a notice. This stays on your device and is not used to build an advertising profile.$seed$, $seed$Offline app files: if you install the website as an app, your browser keeps copies of app files so pages load faster.$seed$]::text[], 10);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Usage statistics$seed$, array[$seed$We use Vercel Web Analytics to count page visits so that we can keep the website working well. According to its provider it does not use cookies and does not identify individual visitors. We do not use it for advertising.$seed$]::text[], '{}'::text[], 20);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$What we do not use$seed$, array[$seed$No advertising cookies, no social-media tracking pixels and no sale of browsing data. If that ever changes, this notice will be updated first and, where the law requires consent, you will be asked before anything is stored.$seed$]::text[], '{}'::text[], 30);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Your choices$seed$, array[$seed$You can clear cookies and site data in your browser settings at any time. Clearing them signs you out and removes your recently viewed list. Blocking necessary cookies will stop sign-in from working.$seed$]::text[], '{}'::text[], 40);

