    $seed$coins-loyalty$seed$, $seed$legal$seed$, $seed$buyers$seed$, $seed$Coins & points$seed$, $seed$Coins & points$seed$,
    $seed$Legal policies$seed$, $seed$Coins and Loyalty Points Terms$seed$, $seed$Coins and loyalty points are two separate records on a retailer account. This page explains each. There is no paid membership on this website.$seed$, $seed$How Coins and loyalty points are added, used, reversed and corrected.$seed$,
    'draft', $seed$1.0$seed$, date '2026-11-14', 170,
    true, true, true, array[$seed$retailer-terms$seed$, $seed$returns$seed$, $seed$suspension-termination$seed$]::text[],
    true
  ) returning id into v_page;

    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Coins$seed$, array[$seed$Coins are a balance on your account. Coins are added when we credit a refund or adjustment to you, for example for goods that were short or damaged at delivery, or for a cancelled order on which Coins had been used.$seed$, $seed$At checkout the available Coins balance may be applied to the order automatically, and the amount applied is shown before you confirm. The rest is paid by Cash on Delivery.$seed$, $seed$If an order is cancelled or returned, Coins used on it are credited back. Each credit is recorded once against the order or delivery, so the same refund cannot be credited twice.$seed$, $seed$Every Coins entry appears in your account ledger with its date and reason.$seed$]::text[], '{}'::text[], 10);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Loyalty points$seed$, array[$seed$Loyalty points are added automatically when an order is delivered: 1 point for every full ₹100 of the order. If the order is later returned, the points for it are removed.$seed$, $seed$Points are a record of your buying activity. They are not money, they have no cash value, they cannot be transferred, and at present they cannot be redeemed against an order. If a redemption scheme is introduced, its terms will be published here first.$seed$, $seed$Points are only ever added by the system on a verified delivery, or adjusted by an Admin with a recorded reason.$seed$]::text[], '{}'::text[], 20);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$Corrections and misuse$seed$, array[$seed$If you think a Coins or points entry is wrong, contact us with the order number. We will check it against the ledger and correct a genuine error.$seed$, $seed$We may reverse Coins or points that were credited by mistake or obtained by fraud or misuse, and will record the reason for doing so.$seed$]::text[], '{}'::text[], 30);

  -- Deliberately NOT published here: see the header. The page stays a draft
  -- until the owner runs a publication stage for its slug.

  insert into public.site_page_admin_notes (page_id, internal_notes, owner_decisions, review_status)
  values (v_page, $seed$Owner verification pending. This wording was published before website content management existed and was carried over verbatim by migration 0105 so no customer-visible policy text changed. It still requires the owner and an Indian legal/tax reviewer to confirm the commercial points listed in the open decisions.$seed$, array[$seed$Whether Coins ever expire (the software sets no expiry; none is stated here).$seed$, $seed$Whether loyalty points will become redeemable, and on what terms.$seed$]::text[], 'owner_review_pending')
  on conflict (page_id) do nothing;
end
$$;

