    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
    values (v_page, $seed$How ordering works$seed$, array[$seed$Approved retailer accounts can maintain a cart and choose a saved delivery address. The order service rechecks product availability, pricing, GST, applicable offers, available Coins and the address at checkout. A pending order is not a delivery guarantee.$seed$, $seed$The application includes marketplace and seller features, subject to configuration. The own-stock sales policies do not provide complete terms for third-party transactions; any launch or ongoing operation requires separate review. Food products are excluded from the stated current scope.$seed$]::text[], '{}'::text[], 10);
    insert into public.site_page_sections (page_id, heading, body, bullets, sort_order)
